import AppKit
import Carbon.HIToolbox

enum Paster {
    /// Self-event marker tag to identify synthetic events generated by Tinycast.
    static let tinycastEventTag: Int64 = 0x54494E59

    /// Write the item onto the pasteboard and paste it into `previousApp` via a synthetic ⌘V.
    @MainActor @discardableResult
    static func paste(
        _ item: ClipboardItem, store: ClipboardStore, previousApp: NSRunningApplication?
    ) -> Bool {
        guard write(item, store: store) else { return false }
        previousApp?.activate()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
            postCommandV(toPid: previousApp?.processIdentifier)
        }
        return true
    }

    /// Put the item on the pasteboard without pasting.
    @MainActor @discardableResult
    static func copy(_ item: ClipboardItem, store: ClipboardStore) -> Bool {
        write(item, store: store)
    }

    /// Put a plain string on the pasteboard without the internal marker.
    @MainActor
    static func copyPlainText(_ text: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.declareTypes([.string], owner: nil)
        pb.setString(text, forType: .string)
    }

    /// Smart Injection (Espanso-style Hybrid Backend):
    /// - For short single-line text (<= 100 chars): Uses Keystroke Backend (`keyboardSetUnicodeString`), leaving pasteboard untouched.
    /// - For multi-line or long text (> 100 chars): Uses Clipboard Backend (NSPasteboard + ⌘V).
    @MainActor
    static func injectString(_ text: String, previousApp: NSRunningApplication?) {
        let pid = previousApp?.processIdentifier
        let isShortSingleLine = text.count <= 100 && !text.contains("\n") && !text.contains("\r")

        if isShortSingleLine {
            typeUnicodeString(text, toPid: pid)
        } else {
            pasteString(text, previousApp: previousApp)
        }
    }

    /// Direct Keystroke Backend: Injects text via `keyboardSetUnicodeString` without touching NSPasteboard.
    @MainActor
    static func typeUnicodeString(_ text: String, toPid pid: pid_t? = nil) {
        guard Permissions.isAccessibilityTrusted() else { return }
        let source = CGEventSource(stateID: .combinedSessionState)

        var chars = Array(text.utf16)
        guard let down = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
              let up = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false) else { return }

        down.setIntegerValueField(.eventSourceUserData, value: tinycastEventTag)
        up.setIntegerValueField(.eventSourceUserData, value: tinycastEventTag)

        down.keyboardSetUnicodeString(stringLength: chars.count, unicodeString: &chars)
        up.keyboardSetUnicodeString(stringLength: chars.count, unicodeString: &chars)

        if let pid {
            down.postToPid(pid)
            up.postToPid(pid)
        } else {
            down.post(tap: .cgAnnotatedSessionEventTap)
            up.post(tap: .cgAnnotatedSessionEventTap)
        }
    }

    /// String counterpart of `paste(_:store:previousApp:)` — marker-stamped so pasted text doesn't re-enter clipboard history.
    @MainActor
    static func pasteString(_ text: String, previousApp: NSRunningApplication?) {
        writeString(text)
        if let previousApp, previousApp != NSWorkspace.shared.frontmostApplication {
            previousApp.activate()
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            postCommandV(toPid: previousApp?.processIdentifier)
        }
    }

    /// String counterpart of `copy(_:store:)`.
    @MainActor
    static func copyString(_ text: String) {
        writeString(text)
    }

    /// String counterpart of `pasteInPlace(_:store:into:)` — ⌘V delivered to the target's process.
    @MainActor
    static func pasteStringInPlace(_ text: String, into app: NSRunningApplication?) {
        writeString(text)
        guard let pid = app?.processIdentifier else { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            postCommandV(toPid: pid)
        }
    }

    @MainActor
    private static func writeString(_ text: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.declareTypes([.string, ClipboardManager.internalType], owner: nil)
        pb.setString(text, forType: .string)
        pb.setData(Data(), forType: ClipboardManager.internalType)
    }

    /// Paste into `app` without activating it (⌘V delivered straight to its process).
    @MainActor @discardableResult
    static func pasteInPlace(
        _ item: ClipboardItem, store: ClipboardStore, into app: NSRunningApplication?
    ) -> Bool {
        guard write(item, store: store) else { return false }
        if let pid = app?.processIdentifier {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                postCommandV(toPid: pid)
            }
        }
        return true
    }

    @MainActor @discardableResult
    private static func write(_ item: ClipboardItem, store: ClipboardStore) -> Bool {
        let pb = NSPasteboard.general
        switch item.kind {
        case .text:
            guard let text = item.text else { return false }
            pb.clearContents()
            pb.declareTypes([.string, ClipboardManager.internalType], owner: nil)
            pb.setString(text, forType: .string)
        case .image:
            guard let url = store.imageURL(for: item), let data = try? Data(contentsOf: url) else {
                return false
            }
            pb.clearContents()
            pb.declareTypes([.png, ClipboardManager.internalType], owner: nil)
            pb.setData(data, forType: .png)
        }
        pb.setData(Data(), forType: ClipboardManager.internalType)
        store.promote(item)
        return true
    }

    /// Synthesize ⌘V — delivered to system tap or pid.
    @MainActor
    private static func postCommandV(toPid pid: pid_t? = nil) {
        guard Permissions.isAccessibilityTrusted() else { return }
        let source = CGEventSource(stateID: .combinedSessionState)

        let v = CGKeyCode(kVK_ANSI_V)
        guard let down = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: true),
              let up = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: false) else { return }

        down.flags = .maskCommand
        up.flags = .maskCommand
        down.setIntegerValueField(.eventSourceUserData, value: tinycastEventTag)
        up.setIntegerValueField(.eventSourceUserData, value: tinycastEventTag)

        if let pid {
            down.postToPid(pid)
            up.postToPid(pid)
        } else {
            down.post(tap: .cgAnnotatedSessionEventTap)
            up.post(tap: .cgAnnotatedSessionEventTap)
        }
    }
}
